#!/usr/bin/env bash
#
# Creates the two KV namespaces, writes their ids into wrangler.jsonc, checks
# the secrets are set, and deploys.
#
# ## Why a script rather than a checklist
#
# The namespace ids are generated by Cloudflare and have to be pasted into
# `wrangler.jsonc` before the Worker can bind them. Doing that by hand is four
# copy-paste steps where a wrong id produces a Worker that deploys fine and
# then fails every request at runtime with an opaque binding error. The script
# reads the ids from `wrangler`'s own output instead.
#
# **Idempotent.** Re-running it is safe and is the normal way to use it: it
# reuses namespaces that already exist rather than creating duplicates, and
# skips the patch if the id is already correct. So it doubles as "make sure the
# deployment matches the config".
#
# ## Usage
#
#     npx wrangler login                      # once, interactive
#     ./scripts/deploy.sh --dry-run           # see what it would do
#     ./scripts/deploy.sh
#
# Secrets are never handled here — `wrangler secret put` is interactive by
# design so the value never lands in a shell history or a CI log. The script
# tells you which ones are missing and stops.

set -euo pipefail

cd "$(dirname "${BASH_SOURCE[0]}")/.."

DRY_RUN=0
SKIP_DEPLOY=0
for arg in "$@"; do
  case "$arg" in
    --dry-run) DRY_RUN=1 ;;
    --no-deploy) SKIP_DEPLOY=1 ;;
    -h|--help)
      sed -n '2,30p' "${BASH_SOURCE[0]}" | sed 's|^# \{0,1\}||'
      exit 0
      ;;
    *) printf 'unknown argument: %s\n' "$arg" >&2; exit 2 ;;
  esac
done

# All progress goes to stderr. `resolve_namespace` returns the namespace id on
# stdout, so a stray `echo` there would be captured as part of the id and
# written into wrangler.jsonc.
say()  { printf '\n\033[1m%s\033[0m\n' "$*" >&2; }
ok()   { printf '  \033[32m✔\033[0m %s\n' "$*" >&2; }
warn() { printf '  \033[33m!\033[0m %s\n' "$*" >&2; }
die()  { printf '\n\033[31m✘ %s\033[0m\n\n' "$*" >&2; exit 1; }

run() {
  if [[ $DRY_RUN == 1 ]]; then
    printf '  \033[2m[dry-run] %s\033[0m\n' "$*" >&2
  else
    "$@"
  fi
}

# ── Preflight ───────────────────────────────────────────────────────────────

say "Preflight"

command -v npx >/dev/null || die "npx not found — install Node."
command -v python3 >/dev/null || die "python3 not found (used to patch wrangler.jsonc)."

# Catch the unauthenticated case up front, or the first `kv` call fails with a
# wall of text about CLOUDFLARE_API_TOKEN that reads like a bug in this script.
#
# Note `wrangler whoami` exits 0 even when it is not authenticated — it reports
# the problem on stdout and returns success — so the exit code is useless here
# and the output has to be inspected.
WHOAMI="$(npx wrangler whoami 2>&1 || true)"
if printf '%s' "$WHOAMI" | grep -qiE 'not authenticated|CLOUDFLARE_API_TOKEN'; then
  die "not logged in to Cloudflare.
    Run:  npx wrangler login
    Or, for CI, set CLOUDFLARE_API_TOKEN."
fi
ok "authenticated as $(printf '%s' "$WHOAMI" | grep -oE '[^ ]+@[^ ]+' | head -1 || echo 'an account')"

# ── Placeholders that must be replaced before this is a real deployment ──────

say "Configuration"

MISSING_CONFIG=()
grep -q 'REPLACE_TEAM_ID' wrangler.jsonc && MISSING_CONFIG+=("APPLE_TEAM_ID is still REPLACE_TEAM_ID")
grep -q '"APP_BUNDLE_ID": "com.example' wrangler.jsonc && MISSING_CONFIG+=("APP_BUNDLE_ID is still com.example.*")

if (( ${#MISSING_CONFIG[@]} )); then
  for item in "${MISSING_CONFIG[@]}"; do warn "$item"; done
  warn "App Attest will reject every device until these match the real app."
  warn "Deploying anyway — the /v1/messages path still works for cache verification."
fi

# The one that is a security problem rather than a convenience problem.
if grep -q '"APP_ATTEST_ENV": "development"' wrangler.jsonc; then
  warn "APP_ATTEST_ENV is \"development\" — accepts debug-build attestations."
  warn "Must be \"production\" before shipping, together with the entitlement"
  warn "in ios/App/PAgent.entitlements."
fi

# ── KV namespaces ───────────────────────────────────────────────────────────

say "KV namespaces"

# `wrangler kv namespace create` prints the id in its output. Reusing an
# existing namespace rather than failing is what makes this re-runnable.
existing_namespaces="$(npx wrangler kv namespace list 2>/dev/null || echo '[]')"

namespace_id_for() {
  local title="$1"
  printf '%s' "$existing_namespaces" | python3 -c "
import json, sys
try:
    for ns in json.load(sys.stdin):
        if ns.get('title') == sys.argv[1]:
            print(ns['id']); break
except Exception:
    pass
" "$title"
}

# Wrangler titles a namespace "<worker-name>-<binding>".
# Read the worker name without a full JSONC parse. A naive `//.*` strip
# corrupts the file — `https://api.deepseek.com/anthropic` contains `//` — so
# this matches the one key it needs.
WORKER_NAME="$(python3 -c "
import re
raw = open('wrangler.jsonc').read()
match = re.search(r'^\s*\"name\"\s*:\s*\"([^\"]+)\"', raw, re.M)
if not match:
    raise SystemExit('could not find \"name\" in wrangler.jsonc')
print(match.group(1))
")"

# Two plain variables rather than an associative array: macOS ships bash 3.2,
# where `declare -A` does not exist. There are exactly two bindings and there
# always will be — they are named in `src/env.ts`.
DEVICES_ID=""
QUOTA_ID=""

resolve_namespace() {
  local binding="$1"
  local title="${WORKER_NAME}-${binding}"
  local id
  id="$(namespace_id_for "$title")"

  if [[ -n "$id" ]]; then
    ok "$binding reusing existing namespace ($id)"
  elif [[ $DRY_RUN == 1 ]]; then
    printf '  \033[2m[dry-run] would create namespace %s\033[0m\n' "$title" >&2
    id="DRY_RUN_ID_${binding}"
  else
    printf '  creating %s …\n' "$title" >&2
    local output
    output="$(npx wrangler kv namespace create "$binding" 2>&1)" || {
      printf '%s\n' "$output" >&2
      die "could not create the $binding namespace."
    }
    # The id appears as a 32-char hex string in the suggested config snippet.
    id="$(printf '%s' "$output" | grep -oE '[0-9a-f]{32}' | head -1)"
    [[ -n "$id" ]] || {
      printf '%s\n' "$output" >&2
      die "created $binding but could not parse its id from the output above."
    }
    ok "$binding created ($id)"
  fi

  printf '%s' "$id"
}

DEVICES_ID="$(resolve_namespace DEVICES)"
QUOTA_ID="$(resolve_namespace QUOTA)"

# ── Patch wrangler.jsonc ────────────────────────────────────────────────────

say "Binding ids"

if [[ $DRY_RUN == 1 ]]; then
  printf '  \033[2m[dry-run] would write ids into wrangler.jsonc\033[0m\n'
else
  python3 - "$DEVICES_ID" "$QUOTA_ID" <<'PYTHON'
import re, sys

devices, quota = sys.argv[1], sys.argv[2]
path = 'wrangler.jsonc'
source = open(path).read()
original = source

# Patch the `id` that follows each binding name, leaving comments and
# formatting untouched — the file is the reviewable source of truth, so a
# JSON round-trip that strips its comments would be a bad trade.
for binding, new_id in (('DEVICES', devices), ('QUOTA', quota)):
    pattern = re.compile(
        r'(\{\s*"binding"\s*:\s*"' + binding + r'"\s*,\s*"id"\s*:\s*")([^"]*)(")'
    )
    match = pattern.search(source)
    if not match:
        sys.exit(f"could not find the {binding} binding in {path}")
    if match.group(2) == new_id:
        print(f"  \033[32m✔\033[0m {binding} id already correct")
        continue
    source = pattern.sub(lambda m: m.group(1) + new_id + m.group(3), source, count=1)
    print(f"  \033[32m✔\033[0m {binding} id written")

if source != original:
    open(path, 'w').write(source)
PYTHON
fi

# ── Secrets ─────────────────────────────────────────────────────────────────

say "Secrets"

# `wrangler secret list` returns the names only, never the values.
secret_names="$(npx wrangler secret list 2>/dev/null || echo '[]')"
have_secret() {
  printf '%s' "$secret_names" | python3 -c "
import json, sys
try:
    print(any(s.get('name') == sys.argv[1] for s in json.load(sys.stdin)))
except Exception:
    print(False)
" "$1" | grep -q True
}

MISSING_SECRETS=()
for secret in DEEPSEEK_API_KEY JWT_SIGNING_KEY; do
  if have_secret "$secret"; then
    ok "$secret is set"
  else
    MISSING_SECRETS+=("$secret")
    warn "$secret is NOT set"
  fi
done

if (( ${#MISSING_SECRETS[@]} )) && [[ $DRY_RUN == 0 ]]; then
  printf '\n'
  warn "Set them before the Worker can serve a request:"
  for secret in "${MISSING_SECRETS[@]}"; do
    case "$secret" in
      DEEPSEEK_API_KEY)
        printf '      npx wrangler secret put DEEPSEEK_API_KEY     # from platform.deepseek.com\n' ;;
      JWT_SIGNING_KEY)
        printf '      openssl rand -base64 48 | npx wrangler secret put JWT_SIGNING_KEY\n' ;;
    esac
  done
  die "missing ${#MISSING_SECRETS[@]} secret(s). Nothing was deployed."
fi

# ── Deploy ──────────────────────────────────────────────────────────────────

if [[ $SKIP_DEPLOY == 1 ]]; then
  say "Skipping deploy (--no-deploy)"
  exit 0
fi

say "Deploy"
run npx wrangler deploy

if [[ $DRY_RUN == 1 ]]; then
  printf '\n\033[2mDry run complete. Nothing was created, patched, or deployed.\033[0m\n\n'
  exit 0
fi

# ── Next step ───────────────────────────────────────────────────────────────

WORKER_URL="$(npx wrangler deployments list 2>/dev/null | grep -oE 'https://[^ ]+\.workers\.dev' | head -1 || true)"

say "Next"
printf '  Verify caching against the live API (R8):\n\n'
if [[ -n "$WORKER_URL" ]]; then
  printf '      node scripts/verify-cache.mjs --target %s\n\n' "$WORKER_URL"
else
  printf '      node scripts/verify-cache.mjs --target https://<your-worker>.workers.dev\n\n'
fi
printf '  \033[2mThat needs JWT_SIGNING_KEY locally to mint a test token — the same\n'
printf '  value you gave the Worker. Export it, or put it in .dev.vars.\033[0m\n\n'
